def afficher_menu(menu):
    print("\n--- MENU ---")
    for numero, pizza in enumerate(menu, start=1):
        prix = pizza["prix_centimes"] / 100
        print(f'{numero}. {pizza["nom"]} - {prix:.2f} €')

def demander_quantite(nom_pizza):
    while True:
        saisie = input(f"Combien de pizzas « {nom_pizza} » ? " )

        try:
            quantite = int(saisie)
        except ValueError:
            print("Saisis un nombre entier, par exemple 0 ou 2.")
            continue

        if quantite < 0:
            print("La quantité ne peut pas être négative.")
            continue

        return quantite

def saisir_commande(menu):
    commande = {}

    for pizza in menu:
        quantite = demander_quantite(pizza["nom"])
        if quantite > 0:
            commande[pizza["nom"]] = quantite

    return commande

def calculer_total_centimes(menu, commande):
    total = 0

    for pizza in menu:
        quantite = commande.get(pizza["nom"], 0)
        total += quantite * pizza["prix_centimes"]

    return total

def afficher_recapitulatif(menu, commande):
    print("\n--- RÉCAPITULATIF ---")

    for pizza in menu:
        quantite = commande.get(pizza["nom"], 0)
        if quantite > 0:
            sous_total = quantite * pizza["prix_centimes"]
            montant = f"{sous_total // 100},{sous_total % 100:02d}"
            print(f'{quantite} x {pizza["nom"]} : {montant} €')

    total = calculer_total_centimes(menu, commande)
    montant_total = f"{total // 100},{total % 100:02d}"
    print(f"Total : {montant_total} €")

def main():
    menu = [
        {"nom": "Margherita", "prix_centimes": 850},
        {"nom": "Reine", "prix_centimes": 1050},
        {"nom": "Quatre fromages", "prix_centimes": 1100},
    ]

    print("Bienvenue à la pizzeria !")
    afficher_menu(menu)
    commande = saisir_commande(menu)
    afficher_recapitulatif(menu, commande)

if __name__ == "__main__":
    main()
